_TCX_BIAS = fnp.asarray([-6.733022955871283e-05, -4.048958069395619e-05, 0.0012136031855749742, -3.181041586676414e-05, -9.685145098524478e-05, -0.0013416143980985445], dtype=fnp.float64)
_TCX_ON = True
_TCX_HOST = [None]
_TCX_STATS = dict(calls=0, layer=None, state_identity=True, released=True)
_TCX_PARENT_FEATURES = final_scalar_features
_TCX_PARENT_GNN = gnn_step
_TCX_PARENT_PREDICT = Estimator.predict

def final_scalar_features(l,m,aux,W):
    result = _TCX_PARENT_FEATURES(l,m,aux,W)
    if _TCX_ON and int(l) == 15:
        assert _TCX_HOST[0] is None
        _TCX_HOST[0] = m
    return result

def _tcx_normalized(x,sigma,raw):
    X = fnp.asarray(x, dtype=fnp.float64)
    context = fnp.concatenate((fnp.mean(X,axis=0), fnp.std(X,axis=0)))
    coefficients = context @ _TCX_WEIGHT + _TCX_BIAS
    alpha = X[:,3]
    phi = X[:,6]
    local = fnp.stack((fnp.ones((int(X.shape[0]),),dtype=fnp.float64), X[:,5], phi, alpha,
                       raw / sigma, (alpha*alpha-1.0)*phi),axis=1)
    return local @ coefficients

def gnn_step(l,x,sigma,W,state,P):
    if not _TCX_ON or int(l) != 15:
        return _TCX_PARENT_GNN(l,x,sigma,W,state,P)
    assert _TMLP_ON and _TCX_HOST[0] is not None
    try:
        answer = _TMLP_PARENT_GNN(l,x,sigma,W,state,P)
        assert x.shape[1] == 30 and answer[1].shape == (x.shape[0],64)
        sig64 = fnp.asarray(sigma,dtype=fnp.float64)
        correction = sig64 * _tmlp_normalized(x,answer[1])
        original_delta = fnp.asarray(answer[0],dtype=fnp.float64)
        delta = original_delta + correction
        raw = _TCX_HOST[0] + original_delta
        delta = delta + sig64 * _tcx_normalized(x,sig64,raw)
        _TMLP_STATS.update(calls=_TMLP_STATS['calls']+1,layer=15,state_identity=True)
        _TCX_STATS.update(calls=_TCX_STATS['calls']+1,layer=15,state_identity=True,released=True)
        return delta,answer[1]
    finally:
        _TCX_HOST[0] = None

def _tcx_predict(self,*args,**kwargs):
    assert _TCX_HOST[0] is None
    try:
        return _TCX_PARENT_PREDICT(self,*args,**kwargs)
    finally:
        _TCX_HOST[0] = None
Estimator.predict = _tcx_predict
